<?php require_once __DIR__.'/../config.php';require_login();$s=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 10');$s->execute([user()['id']]);$orders=$s->fetchAll();$pageTitle='My Account';require __DIR__.'/../includes/header.php';?><section class="page-hero compact"><div class="container"><div class="eyebrow">CUSTOMER SPACE</div><h1>Hello, <span class="gradient-text"><?=e(user()['name'])?></span></h1><p>View your recent orders and account details.</p></div></section><section class="section-pad"><div class="container"><div class="dashboard-panel"><div class="section-heading"><div><h2>Recent Orders</h2><p><?=e(user()['email'])?></p></div><a href="/powervault/logout.php" class="text-link">Log out ↗</a></div><?php if(!$orders): ?><div class="empty-state">You have not placed any orders yet. <a href="/powervault/shop.php">Start shopping</a>.</div><?php else: ?><div class="table-responsive"><table class="table pv-table"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['created_at'])?></td><td><?=money($o['total'])?></td><td><span class="status-pill"><?=e($o['status'])?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></section><?php require __DIR__.'/../includes/footer.php';?>
